SELECT
    fd.id as car_financial_details_id,
    fd.carId as car_id,
    fd.competitorPrice as competitor_price, 
    fd.initialValuationPrice as initial_valuation_price,
    fd.sellerExpectationPrice as seller_expectation_price,
    fd.sellerFirstOffer as seller_first_offer,
    fd.sellerFinalOffer as seller_final_offer,
    fd.reserveAuctionPrice as reserve_auction_price, 
    UNIX_TIMESTAMP(fd.reservedAt) as reserved_at, 
    fd.purchaseChannel as purchase_channel,
    fd.purchasedBy as purchased_by_id, 
    fd.purchasedComment as purchase_comment, 
    fd.saleChannel as sale_channel,
    fd.saleComment as sale_comment, 
    fd.salesRep as sale_rep,
    fd.soldTo as sold_to_id,
    UNIX_TIMESTAMP(fd.boughtAt) as bought_at, 
    UNIX_TIMESTAMP(fd.soldAt) as sold_at, 
    fd.country as country_id,
    UNIX_TIMESTAMP(fd.invoiceDate) as invoice_date, 
    fd.invoiceNumber as invoice_number, 
    fd.b2bDeal as b2b_deal, 
    UNIX_TIMESTAMP(fd.createdAt) as created_at, 
    UNIX_TIMESTAMP(fd.updatedAt) as updated_at, 
    UNIX_TIMESTAMP(fd.deletedAt) as deleted_at, 
    fd.createdByName as created_by,
    fd.createdById as created_by_id,
    fd.updatedByName as updated_by,
    fd.deletedById as deleted_by_id,
    fd.updatedById as updated_by_id,
    fd.deletedByName as deleted_by,
    if(fd.marketplaceVisible=1, true, false) as is_marketplace_visible,
    fd.marketplacePrice as marketplace_price,
    fd.soldToPhoneNumber as sold_to_phone_number,
    fd.availableFinancingOptions as available_financing_options, 
    fd.chosenFinancingOption as chosen_financing_options,
    if(fd.isFeatured=1, true, false) as is_featured,
    UNIX_TIMESTAMP(fd.confirmedAt) as confirmed_at,
    fd.purchaseCancellingReason as purchase_cancellation_reason,
    fd.marketplaceImages as marketplace_images, 
    fd.oldMarketplacePrice as old_marketplace_price, 
    fd.paymentRecipient as payment_recipient,
    fd.paymentType as payment_type, 
    fd.selectedMarketplaces as selected_marketplaces,
    fd.riskIndex as risk_index,
    fd.dealerExecutive as dealer_executive
FROM fcgOrder.financialDetails fd
where fd.updatedAt >= '{{params.start_ts}}' and fd.updatedAt < '{{params.end_ts}}'